const saved=read('al-favorites',[]);let favorites=new Set(Array.isArray(saved)?saved:[]);let contributions=read('al-places',[]);if(!Array.isArray(contributions))contributions=[];
contributions=contributions.filter(p=>p&&typeof p.name==='string'&&typeof p.category==='string'&&typeof p.area==='string'&&Number.isFinite(p.lat)&&Number.isFinite(p.lng)&&Object.keys(profiles).every(k=>[0,1,2].includes(p[k])));
