const overall=p=>p.physical===3?'blocked':Object.keys(profiles).every(k=>p[k]===2)?'full':Object.keys(profiles).some(k=>p[k]>0)?'partial':'unknown';
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200)}
function visiblePlaces(){const q=normalize($('#search').value.trim()),cat=$('#category').value,source=$('#sourceFilter').value;return places.filter(p=>(source==='all'||(source==='local'?p.user:p.source===source))&&(!q||normalize(p.name+' '+p.area+' '+p.category).includes(q))&&(!cat||p.category===cat)&&[...selected].every(k=>p[k]===1||p[k]===2)&&(!onlyFavorites||favorites.has(p.id)))}
function badge(p,k){return `<span class="resource-badge ${p[k]===3?'blocked':p[k]===1?'partial':p[k]===0?'unknown':''}" title="${profiles[k].name}: ${stateLabel(p[k])}"><span class="sr-only">${profiles[k].name}: ${stateLabel(p[k])}</span>${icon(profiles[k].icon)}</span>`}
function render(){const items=visiblePlaces();const origin=$('#sourceFilter').value;$('#dataSummary').textContent=origin==='demo'?'8 exemplos com recursos fictícios, apenas para apresentação.':origin==='local'?'Suas contribuições, salvas somente neste navegador.':imported.meta.accessibilityTagged+' locais com dados de acessibilidade na fonte, incluindo limitações. Demais locais aguardam informações.';$('#resultCount').textContent=`${items.length} ${items.length===1?'local para descobrir':'locais para descobrir'}`;$('#mapCount').textContent=`${items.length} ${items.length===1?'local no mapa':'locais no mapa'}`;$('#results').innerHTML=items.length?items.slice(0,resultLimit).map(p=>`<article class="place-card"><div class="place-art art-${esc(p.art)}" aria-hidden="true">${icon(p.art)}</div><button class="place-main" data-detail="${esc(p.id)}"><h3>${esc(p.name)}</h3><p class="place-meta">${esc(p.category)} · ${esc(p.area)}</p><div class="resource-icons">${Object.keys(profiles).map(k=>badge(p,k)).join('')}<span class="status-text">${p.user?'Sua contribuição':p.source==='osm'?'Fonte: OSM':'Exemplo fictício'}</span></div></button><button class="save-button ${favorites.has(p.id)?'saved':''}" data-save="${esc(p.id)}" aria-pressed="${favorites.has(p.id)}" aria-label="${favorites.has(p.id)?'Remover dos':'Adicionar aos'} favoritos: ${esc(p.name)}">${icon('heart')}</button></article>`).join('')+(items.length>resultLimit?`<button class="secondary" id="loadMore" style="margin:16px 12px">Mostrar mais (${items.length-resultLimit} restantes)</button>`:''):`<div class="empty">${icon('search')}<p>${onlyFavorites?'Nenhum favorito com esses filtros. Salve um local pelo coração.':'Nenhum local encontrado. Tente outra busca ou ajuste os filtros.'}</p><button class="secondary" id="resetResults">Limpar filtros</button></div>`;if(map){markers.clearLayers();items.forEach(p=>{const marker=L.marker([p.lat,p.lng],{icon:L.divIcon({className:'marker-icon',html:`<div class="map-pin ${overall(p)}">${icon(p.art)}</div>`,iconSize:[38,42],iconAnchor:[19,40]}),title:p.name,alt:`Ver detalhes de ${p.name}`});marker.bindTooltip(()=>{const e=document.createElement('span');e.textContent=p.name;return e},{direction:'top',offset:[0,-35]});marker.on('click',()=>detail(p.id));markers.addLayer(marker)})}}
function reset(){resultLimit=30;selected.clear();$('#search').value='';$('#category').value='';$('#sourceFilter').value='osm';onlyFavorites=false;$('#favoritesBtn').setAttribute('aria-pressed','false');document.querySelectorAll('[data-profile]').forEach(b=>b.setAttribute('aria-pressed','false'));render()}
function showModal(html,eyebrow='ACESSIBILIZE'){$('#modalEyebrow').textContent=eyebrow;$('#modalContent').innerHTML=html;icons($('#modalContent'));if(!$('#modal').open)$('#modal').showModal()}
function toggleFavorite(id){favorites.has(id)?favorites.delete(id):favorites.add(id);write('al-favorites',[...favorites]);render()}
function detail(id){const p=places.find(p=>p.id===id);if(!p)return;if(map)map.flyTo([p.lat,p.lng],15,{animate:!matchMedia('(prefers-reduced-motion: reduce)').matches});showModal(`<h2>${esc(p.name)}</h2><div class="detail-category">${esc(p.category)} · ${esc(p.area)}</div><p>${esc(p.address)}</p><p class="notice">${p.user?'Contribuição local não verificada.':p.source==='osm'?'Dados públicos do OpenStreetMap, sem vistoria do Acessibilize.':'Exemplo fictício para demonstração acadêmica.'} Confirme os recursos diretamente com o local antes de visitá-lo.</p>${Object.entries(profiles).map(([k,v])=>`<section class="detail-group"><h3>${icon(v.icon)}${v.name}<span class="resource-badge ${p[k]===3?'blocked':p[k]===1?'partial':p[k]===0?'unknown':''}" title="${stateLabel(p[k])}">${p[k]===2?icon('check'):icon('info')}</span></h3>${p[k]===0?'<span class="unknown-text">Ainda não há informações sobre estes recursos.</span>':`<ul>${(p.source==='osm'?p.resources[k]:p.user?['Recursos declarados por quem cadastrou; detalhes pendentes de verificação.']:p[k]===2?v.features:[v.features[0],'Demais recursos ainda precisam ser confirmados.']).map(f=>`<li>${esc(f)}</li>`).join('')}</ul>`}</section>`).join('')}${p.source==='osm'?`<p><a class="secondary" href="${esc(p.sourceUrl)}" target="_blank" rel="noopener">Consultar registro no OpenStreetMap</a></p><p style="font-size:10px">Importado em ${new Date(imported.meta.retrievedAt).toLocaleDateString('pt-BR')}. A ausência de dados não significa ausência de acessibilidade.</p>`:''}${p.note?`<p><strong>Observação de quem cadastrou:</strong> ${esc(p.note)}</p>`:''}<div class="detail-actions"><button class="secondary" id="modalSave">${icon('heart')}${favorites.has(id)?'Remover favorito':'Salvar local'}</button><a class="primary" href="https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(p.lat+','+p.lng)}" target="_blank" rel="noopener">${icon('arrow')}Abrir trajeto no Google Maps</a></div><p style="font-size:10px">O trajeto externo não garante uma rota acessível.</p>`,'CONHEÇA O ESPAÇO');$('#modalSave').onclick=()=>{toggleFavorite(id);$('#modalSave').innerHTML=icon('heart')+(favorites.has(id)?'Remover favorito':'Salvar local')};}
function about(){showModal('<h2>Uma cidade para<br>todo mundo.</h2><p>O Acessibilize é um protótipo acadêmico de mapa colaborativo para apoiar a autonomia de pessoas com deficiência física, visual e auditiva.</p><ol class="steps"><li><strong>Encontre seu próximo destino</strong>Busque por nome ou bairro em Salvador.</li><li><strong>Escolha o que faz diferença</strong>Combine os filtros. A busca mostra recursos disponíveis ou parciais em todas as categorias selecionadas. Na base real, dados não informados não são presumidos.</li><li><strong>Conheça antes de ir</strong>Compare os recursos físicos, visuais e auditivos de cada espaço.</li><li><strong>Uma cidade construída em conjunto</strong>Adicione um local e salve seus favoritos neste navegador.</li></ol><p class="notice">A base principal importa locais reais do OpenStreetMap, com fonte e data de importação. Só exibimos os recursos de acessibilidade explicitamente informados na fonte, sem vistoria própria. Os oito exemplos fictícios ficam em uma base separada para apresentação. Este protótipo não certifica locais nem calcula rotas acessíveis. Cadastros e favoritos ficam apenas neste navegador, sem envio a um servidor.</p><p>Mapa e base de locais: © OpenStreetMap contributors, sob ODbL 1.0. Interface de mapa: Leaflet.</p>','SOBRE O PROJETO')}
function addPlace(){showModal(`<h2>Mais um lugar.<br>Mais possibilidades.</h2><p>Compartilhe um espaço em Salvador. O cadastro fica salvo apenas neste navegador, como parte da demonstração.</p><form id="placeForm" class="form-grid"><label class="form-field full">Nome do local<input name="name" required maxlength="90" placeholder="Ex.: Centro Cultural do Bairro"></label><label class="form-field">Categoria<select name="category" required><option>Cultura e lazer</option><option>Parques e praças</option><option>Compras</option><option>Serviços</option><option>Alimentação</option></select></label><label class="form-field">Bairro<input name="area" required maxlength="60"></label><label class="form-field full">Endereço<input name="address" required maxlength="180"></label><label class="form-field">Latitude<input name="lat" type="number" step="any" min="-13.1" max="-12.7" value="-12.98" required></label><label class="form-field">Longitude<input name="lng" type="number" step="any" min="-38.65" max="-38.25" value="-38.51" required></label><p class="form-field full" style="margin:0;font-size:10px">Ajuste as coordenadas para posicionar o local na região de Salvador.</p><fieldset><legend>Informações de acessibilidade</legend>${Object.entries(profiles).map(([k,v])=>`<label class="form-field" style="margin:10px 0">${v.name}<select name="${k}"><option value="0">Sem informação</option><option value="1">Recursos parciais</option><option value="2">Recursos disponíveis</option></select></label>`).join('')}</fieldset><label class="form-field full">Quais recursos você encontrou?<textarea name="note" maxlength="600" placeholder="Ex.: rampa na entrada, banheiro adaptado, atendimento em Libras..."></textarea></label><button type="submit" class="primary">${icon('plus')}Adicionar à demonstração</button></form>`,'CONTRIBUA COM O MAPA');$('#placeForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const p={id:'local-'+Date.now(),user:true,name:f.get('name').trim(),category:f.get('category'),area:f.get('area').trim(),address:f.get('address').trim(),lat:Number(f.get('lat')),lng:Number(f.get('lng')),note:f.get('note').trim(),physical:Number(f.get('physical')),visual:Number(f.get('visual')),hearing:Number(f.get('hearing')),art:({'Cultura e lazer':'culture','Parques e praças':'park','Compras':'shopping','Serviços':'service','Alimentação':'food'})[f.get('category')]};if(!p.name||!p.area||!p.address){toast('Preencha o nome, bairro e endereço.');return}const next=[...contributions,p];const persisted=write('al-places',next);contributions=next;places=[...basePlaces,...contributions];reset();$('#sourceFilter').value='local';render();$('#modal').close();if(map)map.flyTo([p.lat,p.lng],15);toast(persisted?'Local adicionado e salvo neste navegador.':'Local adicionado apenas nesta sessão.');};}
const applyFilters=()=>{resultLimit=30;render()};$('#search').addEventListener('input',applyFilters);$('#category').addEventListener('change',applyFilters);$('#sourceFilter').addEventListener('change',applyFilters);$('#clearFilters').onclick=reset;
document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>{const k=b.dataset.profile;selected.has(k)?selected.delete(k):selected.add(k);b.setAttribute('aria-pressed',selected.has(k));render()});
