$('#accessibilityBtn').onclick=()=>{showModal(`<h2>Do seu jeito.</h2><p>Ajuste a leitura da interface. Suas preferências ficam salvas neste navegador.</p><label class="check-row"><input id="largeText" type="checkbox" ${document.body.classList.contains('large-text')?'checked':''}>Aumentar textos da busca e dos locais</label><label class="check-row"><input id="highContrast" type="checkbox" ${document.body.classList.contains('high-contrast')?'checked':''}>Aumentar o contraste da interface</label><p>Use Tab para navegar, Enter para abrir um local e Esc para fechar janelas. Os recursos também são descritos por texto, sem depender apenas das cores.</p>`,'OPÇÕES DE LEITURA');['largeText','highContrast'].forEach((id,i)=>$('#'+id).onchange=e=>{document.body.classList.toggle(i?'high-contrast':'large-text',e.target.checked);write('al-reading',{large:document.body.classList.contains('large-text'),contrast:document.body.classList.contains('high-contrast')})})};
